export const mustacheRe = new RegExp(
  `{{(?<opId>${OPERATOR_ID_PATTERN})\\.(?<inOut>par|out)\\.(?<fieldPath>[\\w-.]+)}}`,
  'g'
)
// Function-style references: op('/path/to/operator').out.val or op("/path/to/operator").out.val
export const fnRe = new RegExp(
  `op\\((?<q>['"])(?<opId>${OPERATOR_ID_PATTERN})\\k<q>\\)\\.(?<inOut>par|out)\\.(?<fieldPath>[\\w-.]+)`,
  'g'
)

// Self-reference shorthand: {{par.fieldPath}} (references current operator's own parameter)
export const selfParMustacheRe = /{{(?<inOut>par)\.(?<fieldPath>[\w-.]+)}}/g

export function getFieldReferences(text: string, thisOpId?: string) {
  const fieldReferences = new Map<string, FieldReference>()

  // Match standard references (with operator ID)
  for (const { groups } of [...text.matchAll(mustacheRe), ...text.matchAll(fnRe)]) {
    const fieldPath = groups?.fieldPath.split('.')[0]
    const opId = thisOpId ? resolvePath(groups?.opId || '', thisOpId) : groups?.opId
    const inOut = groups?.inOut as InOut

    if (!groups || !opId || !fieldPath) {
      debugSetValue(`Invalid operator ID or field path: ${opId}`)
      continue
    }

    // Prevent duplicate references from being added to edges
    const handleId = `${inOut}.${fieldPath}`
    const fullPath = `${opId}.${handleId}`
    if (fieldReferences.has(fullPath)) {
      continue
    }
    const ref = { fieldPath, opId, inOut: groups?.inOut as InOut, handleId } as FieldReference
    fieldReferences.set(fullPath, ref)
  }

  // Match self-parameter shorthand ({{par.fieldPath}})
  if (thisOpId) {
    for (const { groups } of text.matchAll(selfParMustacheRe)) {
      const fieldPath = groups?.fieldPath.split('.')[0]
      const inOut = groups?.inOut as InOut // Always 'par'

      if (!groups || !fieldPath) continue

    setValue(field.value)
  })
  return () => sub.unsubscribe()
}, [field])

// Sync reference edges when field value changes
// This effect should NOT depend on edges to avoid infinite loops
const fieldReferences = useMemo(() => getFieldReferences(value, thisOpId), [value, thisOpId])

useEffect(() => {
  setEdges(oldEdges => {
    // Find existing ReferenceEdges targeting this field
    const existingReferenceEdges = oldEdges.filter(
      e => e.target === nodeId && e.targetHandle === thisFieldId && e.type === 'ReferenceEdge'
    )

    // Determine which edges to add and remove
    const existingHandleIds = new Set(existingReferenceEdges.map(e => e.sourceHandle))
    const referencedHandleIds = new Set(fieldReferences.map(ref => ref.handleId))

    const toAdd = fieldReferences.filter(ref => !existingHandleIds.has(ref.handleId))
    const idsToRemove = new Set(
      existingReferenceEdges
        .filter(e => !referencedHandleIds.has(e.sourceHandle || ''))
        .map(e => e.id)
    )

    if (toAdd.length === 0 && idsToRemove.size === 0) {
      return oldEdges // No changes needed
    }

    let newEdges = oldEdges

    // Remove edges that are no longer referenced
    if (idsToRemove.size > 0) {
      newEdges = newEdges.filter(e => !idsToRemove.has(e.id))
    }

    // Add new reference edges
    if (toAdd.length > 0) {
      const newReferenceEdges = toAdd.map(({ opId, handleId }) => {
        const connection = {
          source: opId,
          sourceHandle: handleId,
          target: thisOpId,
          targetHandle: thisFieldId,
        }
        return {
          id: edgeId(connection),
          type: 'ReferenceEdge',
          selectable: false,
          deletable: false,
          focusable: false,
          reconnectable: false,
          source: opId,
          target: thisOpId,
          sourceHandle: handleId,
          targetHandle: thisFieldId,
        } as Edge<Operator<IOperator>, Operator<IOperator>>
      })

      newEdges = [...newEdges, ...newReferenceEdges]
    }

    return newEdges
  })
}, [fieldReferences, thisOpId, thisFieldId, nodeId, setEdges])

